// Decision checklist in pseudocode
if (needsFullAuditTrail) return YES;
if (needsStateAtPointInTime) return YES;
if (multipleServicesNeedSharedHistory) return YES;
if (domainHasClearTemporalBusinessRules) return YES;
// Otherwise, prefer traditional CRUD
return CONSIDER_CRUD_FIRST;

